"use client";

/**
 * Label: the visible name of a form control.
 * Purpose: wraps Radix Label, so clicking the label focuses its control. Generated by shadcn, then
 *   re-themed to Grove. Owner: design system. The required marker and "(optional)" text: S2-T04/T05.
 * Props: every Radix Label prop (htmlFor to pair it with a control).
 * Responsive: none. Accessibility: every control has a label; placeholders are not labels.
 * States: none. Dependencies: radix Label, cn. Tests: controls.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .label).
 */
import { Label as LabelPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function Label({ className, ...props }: ComponentProps<typeof LabelPrimitive.Root>) {
  return (
    <LabelPrimitive.Root
      data-slot="label"
      className={cn("text-small font-semibold text-ink select-none", className)}
      {...props}
    />
  );
}

export { Label };
